INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.124.1',
  '2026-10-29',
  'Пульт ТВ: в выборе папки не открывался раздел',
  E'В админке, в «Папки под кодом» и в «📥 В папку…», выбор раздела ничего не делал: окно закрывалось, папки раздела не показывались, и было непонятно, что дальше. Теперь раздел открывается и показывает папки, как и задумано.\n\nЗаодно в списке закрытых папок больше не пишется «закрыта 01.01 04:00» — там теперь настоящая дата.',
  E'Гонка в обработчиках окна выбора. Обработчик `data-modal` (закрывает окно и возвращает ответ) повешен на `#mbox` РАНЬШЕ обработчика, который запоминает нажатую папку. При настоящем клике браузер делает обход микрозадач между вызовами обработчиков, поэтому продолжение `await modal(...)` выполнялось ДО записи выбора и видело `pickAnswer === null` → `pickFolder` молча возвращал null. Программный `element.click()` так не делает (микрозадачи откладываются до конца скрипта), из-за чего браузерный прогон на стенде проходил, а живой клик — нет.\n\nПочинено фазой: обработчики выбора (`data-pickgo`/`data-picksel`/`data-pickup`, `data-into`, `data-plist` и `data-plpick` в `addToPlaylist`) переведены на фазу ПЕРЕХВАТА — она всегда раньше всплытия, независимо от порядка регистрации. Та же гонка была у «📥 Файлы / ZIP / По ссылке» (`adminState.intoMode`) и у выбора плейлиста — они чинятся тем же изменением.\n\nВторое: `adminLocks` не клал `Set` в `lockView`, и в карточке замка стояло 01.01.1970. Добавлен `lockStore.at(path)` (наружу уходит только время — соль и хеш кода не покидают хранилища) и проверка в тесте.'
);
-- +goose StatementEnd

